def compute(vars):
    useful_life = vars["v1"]
    if useful_life == 0:
        return None

    depreciation_rate = (1 / useful_life) * 100

    return {
        "value": depreciation_rate,
        "trace": {
            "useful_life_years": useful_life,
            "depreciation_rate_percent": depreciation_rate,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
